      question: "Create middleware for A/B testing",
      answer: "Use cookies to persist variant assignment, rewrite to variant pages based on assignment.",
      example: "// middleware.js\nimport { NextResponse } from 'next/server';\n\nexport function middleware(request) {\n  const { pathname } = request.nextUrl;\n  const variant = request.cookies.get('ab-test')?.value;\n  \n  if (pathname === '/') {\n    let assignedVariant = variant;\n    \n    if (!assignedVariant) {\n      assignedVariant = Math.random() < 0.5 ? 'control' : 'treatment';\n      \n      const url = request.nextUrl.clone();\n      url.pathname = assignedVariant === 'control' ? '/home-control' : '/home-treatment';\n      \n      const response = NextResponse.rewrite(url);\n      response.cookies.set('ab-test', assignedVariant, {\n        maxAge: 30 * 24 * 60 * 60,\n        path: '/',\n      });\n      \n      return response;\n    }\n    \n    const url = request.nextUrl.clone();\n    url.pathname = variant === 'control' ? '/home-control' : '/home-treatment';\n    return NextResponse.rewrite(url);\n  }\n  \n  return NextResponse.next();\n}",
