      question: "Implement accessibility improvements with ARIA",
      answer: "Add ARIA attributes, keyboard navigation, and focus management for better accessibility.",
      example: "// app/components/AccessibleButton.jsx\n'use client';\n\nexport default function AccessibleButton({ onClick, children, disabled = false }) {\n  const handleKeyDown = (e) => {\n    if (e.key === 'Enter' || e.key === ' ') {\n      e.preventDefault();\n      onClick(e);\n    }\n  };\n  \n  return (\n    <button\n      onClick={onClick}\n      onKeyDown={handleKeyDown}\n      disabled={disabled}\n      aria-disabled={disabled}\n      aria-label={typeof children === 'string' ? children : 'Button'}\n      style={{ padding: '10px 20px', cursor: disabled ? 'not-allowed' : 'pointer' }}\n    >\n      {children}\n    </button>\n  );\n}",
